INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 38, 'theory', 'Quiz: algorithms in Rust');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 38, 0, 'Why is the middle in binary search computed as lo + (hi - lo) / 2?', '["It is faster", "The sum lo + hi can overflow on large indices", "The compiler requires it", "To round up"]', 1, 'The form lo + (hi - lo) / 2 is safe for any valid bounds.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 38, 1, 'How do you get a min-heap from std::collections::BinaryHeap?', '["Call the min_heap() method", "Wrap the elements in std::cmp::Reverse", "Sort the vector", "You can''t"]', 1, 'BinaryHeap is a max-heap; Reverse flips the order of comparison.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 38, 2, 'Why is 3usize - 5 dangerous?', '["It isn''t, the result is -2", "usize has no sign: a panic in debug, a huge number in release; use checked_sub / saturating_sub", "It won''t compile", "The result is 0"]', 1, 'Pick an explicit operation: checked, saturating, wrapping or overflowing.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 38, 3, 'What does the distance array Vec<Option<u32>> hold in breadth-first search?', '["Only reachable vertices", "Some(distance) for reached vertices and None for unreachable ones", "Parent numbers", "Edge weights"]', 1, 'Option naturally encodes "not visited yet / unreachable".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 38, 4, 'What does path compression give in a disjoint set union?', '["It reduces memory", "It redirects the visited vertices to the root, so later lookups are almost instant", "It sorts the elements", "It removes cycles from the graph"]', 1, 'Together with union by size it gives almost constant amortized time.');
